# ## 2. Knowledge spaces and outer fringes
# 
# Enumerate prerequisite-closed subsets and compute admissible one-item extensions. Check against the archived states and fringes.

items = defaultdict(set)
edges = defaultdict(set)
for r in DATA['items']:
    items[r['domain_id']].add(r['canonical_item_id'])
for r in DATA['edges']:
    edges[r['domain_id']].add((r['prerequisite_item_id'], r['target_item_id']))
truth = {}
for domain, domain_items in sorted(items.items()):
    ordered = sorted(domain_items)
    states = {frozenset(c) for n in range(len(ordered)+1) for c in combinations(ordered,n)
              if all(b not in c or a in c for a,b in edges[domain])}
    archived = [r for r in DATA['states'] if r['domain_id'] == domain]
    assert states == {frozenset(r['mastered_items']) for r in archived}
    for r in archived:
        mastered = frozenset(r['mastered_items'])
        fringe = {q for q in domain_items-mastered if mastered | {q} in states}
        direct = {q for q in domain_items-mastered if all(a in mastered for a,b in edges[domain] if b == q)}
        assert fringe == direct == set(r['fringe_items'])
        truth[domain,r['state_id']] = (mastered, fringe)
    print(domain, ':', len(domain_items), 'components,', len(edges[domain]), 'edges,', len(states), 'states')
assert len(truth) == 50 and sum(map(len, items.values())) == 23


# ## 3. Scoring
# 
# Metrics are calculated per response and macro-averaged. Two empty sets score 1. An empty prediction with a nonempty target scores 0. A nonempty prediction with an empty target has recall 1; precision, F1 and Jaccard are 0.

MODEL_LABELS = {
    "gpt-5.6-sol": "GPT-5.6 Sol",
    "gpt-5.6-terra": "GPT-5.6 Terra",
    "claude-fable-5": "Claude Fable 5",
    "claude-sonnet-5": "Claude Sonnet 5",
    "gemini-3.1-pro-preview": "Gemini 3.1 Pro Preview",
    "gemini-3.7-flash": "Gemini 3.7 Flash",
}

def score(predicted: set[str], expected: set[str]) -> dict:
    tp, fp, fn = len(predicted & expected), len(predicted - expected), len(expected - predicted)
    precision = tp / (tp + fp) if tp + fp else (1.0 if not expected else 0.0)
    recall = tp / (tp + fn) if tp + fn else 1.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    union = predicted | expected
    return {"tp": tp, "fp": fp, "fn": fn, "precision": precision, "recall": recall,
            "f1": f1, "jaccard": len(predicted & expected) / len(union) if union else 1.0,
            "exact": int(predicted == expected)}

def aggregate(rows: list[dict], keys: tuple[str, ...]) -> list[dict]:
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(str(row[k]) for k in keys)].append(row)
    result = []
    for values, group in sorted(groups.items()):
        result.append({**dict(zip(keys, values)), "n": len(group),
                       "schema_valid_n": sum(r["schema_valid"] for r in group),
                       "schema_valid_rate": mean(r["schema_valid"] for r in group),
                       "exact_n": sum(r["exact"] for r in group),
                       "exact_accuracy": mean(r["exact"] for r in group),
                       "precision_macro": mean(r["precision"] for r in group),
                       "recall_macro": mean(r["recall"] for r in group),
                       "f1_macro": mean(r["f1"] for r in group),
                       "jaccard_macro": mean(r["jaccard"] for r in group)})
    return result

def bootstrap_ci(values: list[float], rng: random.Random, draws: int = 10000) -> tuple[float, float]:
    estimates = sorted(mean(rng.choices(values, k=len(values))) for _ in range(draws))
    return estimates[int(.025 * draws)], estimates[int(.975 * draws)]

def signflip_p(values: list[float], rng: random.Random, draws: int = 100000) -> float:
    observed = abs(mean(values))
    exceed = 1
    for _ in range(draws):
        simulated = abs(mean(v if rng.random() < .5 else -v for v in values))
        exceed += simulated >= observed - 1e-15
    return exceed / (draws + 1)

def holm(rows: list[dict]) -> None:
    ordered = sorted(enumerate(rows), key=lambda pair: pair[1]["p_unadjusted"])
    running = 0.0
    m = len(rows)
    for rank, (index, row) in enumerate(ordered):
        running = max(running, min(1.0, (m - rank) * row["p_unadjusted"]))
        rows[index]["p_holm"] = running

def md_table(headers: list[str], rows: list[list[str]]) -> str:
    return "\n".join(["| " + " | ".join(headers) + " |",
                      "| " + " | ".join(["---"] * len(headers)) + " |"] +
                     ["| " + " | ".join(row) + " |" for row in rows])

def pct(value: float) -> str:
    return f"{100 * value:.1f}%"

assert score(set(),set())['f1'] == 1
assert score(set(),{'a'})['f1'] == 0
assert score({'a'},set())['f1'] == 0
assert score({'a','b'},{'b','c'})['jaccard'] == 1/3
rows = []
for r in DATA['responses']:
    predicted = {r['position_to_canonical_id'][str(p)] for p in r['recommended_positions']}
    mastered, expected = truth[r['domain_id'],r['state_id']]
    assert predicted <= items[r['domain_id']]
    rows.append(dict(r, model=MODEL_LABELS[r['model_id']], domain=r['domain_id'],
                     schema_valid=1, predicted=sorted(predicted), expected=sorted(expected),
                     terminal=int(mastered == items[r['domain_id']]), **score(predicted,expected)))
cells_seen = {(r['model_id'],r['domain'],r['state_id'],r['condition'],r['kc_order']) for r in rows}
assert len(rows) == len(cells_seen) == 2400
assert {r['condition'] for r in rows} == {'P0','P1','P2','P3'}
assert {r['kc_order'] for r in rows} == {1,2}
assert {r['model_id'] for r in rows} == set(MODEL_LABELS)
tables = {}
for name, keys in [
    ('metrics_by_condition_balanced.csv', ('condition',)),
    ('metrics_by_model_available.csv', ('model',)),
    ('metrics_by_domain_balanced.csv', ('domain',)),
    ('metrics_by_condition_domain_balanced.csv', ('condition','domain')),
    ('metrics_by_condition_model_balanced.csv', ('condition','model'))]:
    tables[name] = aggregate(rows,keys)
print(md_table(['Condition','n','Exact','Precision','Recall','F1','Jaccard'],
    [[r['condition'],str(r['n'])] + [pct(r[k]) for k in
      ['exact_accuracy','precision_macro','recall_macro','f1_macro','jaccard_macro']]
     for r in tables['metrics_by_condition_balanced.csv']]))
overall = aggregate([dict(r, all='Overall') for r in rows], ('all',))[0]
print('Overall exact:', pct(overall['exact_accuracy']))


# ## 4. Condition contrasts
# 
# Equal weighting of 50 domain-specific states; averages over six models and two orders per condition. Seed: 20260909. Bootstrap: 10,000 draws; percentile indices 250 and 9,750 (zero-based). Two-sided sign-flip tests: 100,000 draws with plus-one correction. Holm adjustment across three exact-accuracy contrasts. The original iteration order and shared random stream are retained.
# 
# Intervals and tests are descriptive. Presentation agreement does not separate order effects from sampling variation.

state_means = defaultdict(lambda: defaultdict(list))
for r in rows:
    state_means[r['domain'],r['state_id']][r['condition']].append(r)
assert len(state_means) == 50
assert all(set(d) == {'P0','P1','P2','P3'} and all(len(v)==12 for v in d.values()) for d in state_means.values())
contrasts = []
rng = random.Random(SEED)
for left,right in [('P1','P0'),('P2','P1'),('P3','P2')]:
    record = {'contrast': f'{left} - {right}', 'n_unique_states': len(state_means)}
    for metric in ['exact','precision','recall','f1','jaccard']:
        differences = [mean(r[metric] for r in d[left])-mean(r[metric] for r in d[right]) for d in state_means.values()]
        lo,hi = bootstrap_ci(differences,rng)
        record.update({f'{metric}_difference':mean(differences), f'{metric}_ci_low':lo, f'{metric}_ci_high':hi})
        if metric == 'exact':
            record['p_unadjusted'] = signflip_p(differences,rng)
    contrasts.append(record)
holm(contrasts)
tables['condition_contrasts_balanced.csv'] = contrasts
for r in contrasts:
    print(r['contrast'], ':', round(100*r['exact_difference'],3), 'pp; 95% CI',
          [round(100*r[k],3) for k in ['exact_ci_low','exact_ci_high']], '; Holm p =', r['p_holm'])


# ## 5. Presentation agreement and terminal states

pairs = defaultdict(dict)
for r in rows:
    pairs[r['model_id'],r['condition'],r['domain'],r['state_id']][r['kc_order']] = set(r['predicted'])
assert len(pairs) == 1200 and all(set(p)=={1,2} for p in pairs.values())
agreements = [score(p[1],p[2]) for p in pairs.values()]
order = {'complete_pairs':len(pairs), 'valid_pairs':len(pairs),
         'exact_agreement':mean(r['exact'] for r in agreements), 'jaccard':mean(r['jaccard'] for r in agreements)}
terminal = {'n_responses':sum(r['terminal'] for r in rows), 'exact':mean(r['exact'] for r in rows if r['terminal'])}
print('Order agreement:', format(100*order['exact_agreement'],'.2f')+'%', '; Jaccard:', pct(order['jaccard']))
print('Terminal responses:', terminal)


# ## 6. Verification and export
# 
# Compare six tables and overall, order-agreement and terminal-state statistics with the archived analysis (absolute tolerance: 1e-12). Export CSV and JSON. Figure data are included; PDF figures are not rendered.

def compare(actual, expected):
    assert len(actual) == len(expected)
    for a,e in zip(actual,expected):
        assert set(a) == set(e)
        for k,v in a.items():
            if isinstance(v,(int,float)):
                assert abs(v-float(e[k])) < 1e-12, (k,v,e[k])
            else:
                assert v == e[k], (k,v,e[k])
for name, table in tables.items():
    compare(table, DATA['reference_tables'][name])
    with (OUT/name).open('w',encoding='utf-8',newline='') as f:
        writer = csv.DictWriter(f,fieldnames=list(table[0]))
        writer.writeheader()
        writer.writerows(table)
compare([overall],[DATA['reference_summary']['available_case']])
compare([order],[DATA['reference_summary']['order']])
compare([terminal],[DATA['reference_summary']['terminal']])
summary = {'python':platform.python_version(), 'seed':SEED, 'responses':len(rows),
           'overall':overall,'order':order,'terminal':terminal,'checks':'All reference comparisons passed'}
(OUT/'verification.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
(OUT/'response_metrics.json').write_text(json.dumps(rows,indent=2)+'\n',encoding='utf-8')
print('PASS: all six tables and overall/order/terminal statistics reproduce the archived analysis.')
print('Outputs:', OUT.resolve())


